int main(){namespace fs=std::filesystem;auto root=fs::current_path()/"Tests"/".phase5-core";std::error_code ec;fs::remove_all(root,ec);fs::create_directories(root/"history"/"StyleA");std::string error;StyleGenerationConfig c;c.baseModel="base";c.loraPath="style.safetensors";c.prompt="prompt";c.outputDirectory="output";c.imageCount=3;c.styleName="StyleA";c.adapters.push_back({"style","style.safetensors",.7f});c.comparisons.push_back({"StyleA","style.safetensors",.7f});if(!SaveGenerationConfig(c,root/"generation.json",error))return 1;std::ifstream config(root/"generation.json");std::string json((std::istreambuf_iterator<char>(config)),{});if(json.find("\"adapters\"")==std::string::npos||json.find("\"image_count\": 3")==std::string::npos)return 2;if(!EnsureDefaultTrainingPresets(root/"TrainingPresets",error)||ScanTrainingPresets(root/"TrainingPresets",error).size()!=2)return 3;std::ofstream(root/"history"/"StyleA"/"one.png")<<"png";std::ofstream(root/"history"/"StyleA"/"one.json")<<"{\"style_name\":\"StyleA\",\"prompt\":\"hello\",\"seed\":7,\"lora_strength\":0.7}";auto history=ScanGenerationHistory(root/"history",error);if(history.size()!=1||history[0].styleName!="StyleA"||history[0].seed!=7)return 4;if(!DeleteGenerationHistoryEntry(history[0],error)||fs::exists(history[0].imagePath)||fs::exists(history[0].jsonPath))return 5;fs::remove_all(root,ec);std::cout<<"Phase 5 config, training presets, history scan/delete passed.\n";}
